const ev = $('Dev Desk Webhook').item.json.body;
const data = ev.data || {};
const plan = data.plan || {};
const ticket = (data.ticket_no || 'DEV').toString();
const branch = 'agent/' + ticket.toLowerCase();
let aiNotes = '';
try { aiNotes = $('Free AI: implementation notes').item.json.choices?.[0]?.message?.content || ''; } catch (e) {}
const list = (t, a) => (Array.isArray(a) && a.length) ? ('\n### ' + t + '\n' + a.map(x => '- ' + x).join('\n') + '\n') : '';
const prBody = '**Ticket:** ' + ticket + '  \u2022  **Type:** ' + (data.kind || '') + '\n\n' +
  '**Summary:** ' + (plan.summary || data.title || '') + '\n' +
  list('What to build / fix', plan.changes) + list('Areas', plan.areas) +
  list('Risks', plan.risks) + list('How to test', plan.tests) +
  (aiNotes ? ('\n---\n### AI implementation notes\n' + aiNotes + '\n') : '') +
  '\n---\n_Auto-created from a TutiPays AI Dev Desk approval. This is a draft \u2014 review and complete the code before merge._';
const spec = '# ' + ticket + ' \u2014 ' + (data.title || '') + '\n\n' + (data.description || '') + '\n\n## Approved plan\n\n```json\n' + JSON.stringify(plan, null, 2) + '\n```\n';
return [{ json: {
  owner: 'techsaluent',
  repo: 'RBPAYS',
  base: 'main',
  branch,
  ticket,
  prTitle: '[' + (data.kind || 'task') + '] ' + (data.title || ticket) + ' (' + ticket + ')',
  prBody,
  specPath: 'docs/dev-agent/' + ticket + '.md',
  specContentB64: Buffer.from(spec).toString('base64')
} }];
